// Glyphs drawn from SVG path data, so they render as vectors in the window, in ImageRenderer and in the icon.
//
// Meaning icons are Heroicons 20 solid (MIT, github.com/tailwindlabs/heroicons), read from @heroicons/react
// in a Prototemplate checkout with skills/gt-deck/scripts/heroicon-symbol.mjs.
// The agent marks come from thesvg.org: claude/default (CC0-1.0, #D97757) and codex-openai/default (MIT),
// the Codex mark that OpenAI's Codex app uses, drawn in the current ink.

struct GlyphPath: Sendable {
    var d: String
    var eoFill: Bool

    static func evenOdd(_ d: String) -> GlyphPath { GlyphPath(d: d, eoFill: true) }
    static func nonZero(_ d: String) -> GlyphPath { GlyphPath(d: d, eoFill: false) }
}

